package fuse

import (
	"math"
	"testing"
)

// Every gG band against every vertex of the ABB curve it was fitted to,
// not only the eleven fitted points: a three-body ladder cannot follow the
// curve's whole shape (see gg), so the bound is loose, 0.5 decades, and
// only catches a regression.
func TestGGBandsAgainstTheWholeABBCurve(t *testing.T) {
	p := profile(t, IecGg)
	for _, b := range p.Bands {
		vs := abbVertices[b.RatingA]
		if len(vs) != 48 {
			t.Fatalf("%g A: %d ABB vertices", b.RatingA, len(vs))
		}
		var sq, worst, worstAt float64
		for _, v := range vs {
			got := b.MeltSeconds(v[0], RefAmbientC)
			d := math.Log10(got / v[1])
			if math.IsInf(got, 1) {
				d = math.Inf(1)
			}
			sq += d * d
			if math.Abs(d) > math.Abs(worst) {
				worst, worstAt = d, v[0]
			}
		}
		rms := math.Sqrt(sq / float64(len(vs)))
		t.Logf("%g A: rms %.3f decades, worst %+.2f at %.2f ×", b.RatingA, rms, worst, worstAt)
		if math.Abs(worst) > 0.5 {
			t.Errorf("%g A: %+.2f decades from ABB at %.2f ×, want within 0.5", b.RatingA, worst, worstAt)
		}
	}
}

